"""
    if the words are all in lowercase

    >>> all_lowercase(["a", "b", "c"])
    True
    >>> all_lowercase(["a", "12b", "c12"])
    True
    >>> all_lowercase(["a", "12b", "C12"])
    False
    """
def all_lowercase(title_words: Any) -> object {
    concat_str = ''.join(title_words);
    return (concat_str.lower() == concat_str);
}

"""
    Coerces pathlib Path objects to a string (only python version 3.6+)
    any other objects passed to this function will be returned as is.
    This WILL NOT work with on Python 3.4, 3.5 since the __fspath__ dunder
    method did not exist in those verisions, however psychopy does not support
    these versions of python anyways.

    :Parameters:

    filepath : str or pathlib.Path
        file system path that needs to be coerced into a string to
        use by Psychopy's internals

    :Returns:

    filepath : str or same as input object
        file system path coerced into a string type
    """
def pathToString(filepath: Any) -> object {
    if hasattr(filepath, "__fspath__") {
        return filepath.__fspath__();
    }
    return filepath;
}

"""
    Returns a truncated string with '..' at the end if it is longer than the length parameter.
    If the title param is true a span with the original string as title (for mouse over) is added.
    """
def truncate_string(string: Any, length: Any = 80, title: Any = True) -> object {
    if (string is None) {
        return '';
    }
    if (len(string) > (length + 2)) {
        if title {
            title = string.replace('"', '');
            string = (
                '<span title="' + title + '">' + string[:length] + '..' + '</span>'
            );
        } else {
            string = string[:length] + '..';
        }
    }
    return string;
}

