"""
    Encodes some things as HTML Entities, making them safe to print anywhere.

    Currently changes [&<>'"] "'# work around Emacs bug...
    """
def encodeHTML(string: Any) -> object {
    return string.replace('&', '&amp;').replace('<', '&lt;').replace(
        '>', '&gt;'
    ).replace(
        '"', '&quot;'
    ).replace(
        "'", '&apos;'
    );
}

"""Returns a usage string if one exists
    else creates a usage string in the form of:

        -o option_name OPTIONNAME
    """
def get_option_usage_string(name: Any, option: Any) -> object {
    usage_str = option.get("usage");
    if not usage_str {
        usage_str = f"-o {name} {str.upper(name.replace('_', ''))}";
    }
    return usage_str;
}

